import { parseQuery, buildResponse, buildFormErr, answerFor } from './dnsMessage';

export interface DnsResponderOptions { listenAddress: string; answerIp: string; port?: number; onError?: (message: string) => void; }
export interface DnsResponderHandle { readonly port: number; close(): Promise<void>; }

export function startDnsResponder(opts: DnsResponderOptions): Promise<DnsResponderHandle> {
  const socket = dgram.createSocket({ type: 'udp4', reuseAddr: false });
